"Das Restpolynom {0} hat <1>keine rationale Nullstelle</1> und lässt sich hier nicht in Wurzeln auflösen. <2>Numerische Näherung</2> der reellen Nullstellen: {3}, {4}.": "The remaining polynomial {0} has <1>no rational zero</1> and cannot be solved in radicals here. <2>Numerical approximation</2> of the real zeros: {3}, {4}.",
