"Fläche konnte nicht berechnet werden — f ist im Intervall evtl. nicht (umkehrbar) definiert.": "Area could not be computed — f may not be defined (or invertible) on the interval.",
"Fläche zwischen Funktionen": "Area between Functions",
"Fläche zwischen f und der y-Achse im Intervall [{0}, {1}] (y-Werte)": "Area between f and the y-axis on the interval [{0}, {1}] (y-values)",
"Fläche zwischen f und {0} im Intervall [{1}, {2}]": "Area between f and {0} on the interval [{1}, {2}]",
"Fläche zwischen zwei Funktionsgraphen. Man zieht die untere Funktion von der oberen ab und integriert. Vorzeichen beachten — bei Vorzeichenwechsel der Differenz aufteilen.": "Area between two function graphs. Subtract the lower function from the upper one and integrate. Mind the signs — if the difference changes sign, split the interval.",
"Fläche zwischen {0}=x² und {1}=x: A = ∫[{2}] (x−x²)dx = {3}/{4}": "Area between {0}=x² and {1}=x: A = ∫[{2}] (x−x²)dx = {3}/{4}",
