"Fläche ≈ {0} <1>(numerische Näherung)</1>": "Area ≈ {0} <1>(numerical approximation)</1>",
"Flächeninhalt zwischen Graphen": "Area between graphs",
"Form aufschalten, dann a, b, c bzw. a, v, h oben mit den Schiebereglern verändern.": "Add a form, then adjust a, b, c (or a, v, h) with the sliders above.",
"Form aufschalten, dann a, b, c und d oben mit den Schiebereglern verändern (a = Amplitude, b = Frequenz, c = Phasenverschiebung, d = Verschiebung nach oben/unten).": "Add the form, then adjust a, b, c and d above with the sliders (a = amplitude, b = frequency, c = phase shift, d = vertical shift).",
"Formen (Schieberegler)": "Forms (sliders)",
"Freie Punkte": "Free points",
"Funktion": "Function",
"Funktion eingeben und aufschalten: Punkt A und Punkt B sind beide ziehbar. Ziehe A und B nahe zusammen — der Differenzenquotient nähert sich dann dem Differentialquotienten (der Ableitung) an.": "Enter a function and activate it: point A and point B are both draggable. Drag A and B close together — the difference quotient then approaches the differential quotient (the derivative).",
"Funktion eingeben und aufschalten: die Intervallgrenzen a und b sind ziehbar. Ober-/Untersumme zwischen f und der x-Achse — erhöhe n, um dich dem exakten Integral anzunähern.": "Enter a function and activate it: the interval bounds a and b are draggable. Upper/lower sum between f and the x-axis — increase n to approach the exact integral.",
"Funktion eingeben, Randart wählen und aufschalten: die Intervallgrenzen a und b sind ziehbar (und frei eintippbar).": "Enter a function, choose the boundary type, and activate: the interval bounds a and b are draggable (and freely typeable).",
"Funktion, bei der die Variable im Exponenten steht. Für b {0} {1}: exponentielles Wachstum. Für {2} {3} b {4} {5}: exponentieller Zerfall. Immer positiv, keine Nullstelle. Definitionsbereich: ℝ.": "Function in which the variable is in the exponent. For b {0} {1}: exponential growth. For {2} {3} b {4} {5}: exponential decay. Always positive, no zero. Domain: ℝ.",
"Funktionenplotter": "Function Plotter",
"Funktionsbeschriftung im Plot": "Function labels in plot",
"Funktionstyp: {0} = {1}·{2}ˣ": "Function type: {0} = {1}·{2}ˣ",
"Fülle mindestens {0} der {1} Felder aus — das leere Feld wird automatisch berechnet.": "Fill in at least {0} of the {1} fields — the empty one is computed automatically.",
"Für die Senkrechte: Punkt und Gerade im Plot wählen. Für die Mittelsenkrechte: zwei Punkte wählen. Inkl. Lösungsweg und Beziehung der Steigungen (m₁·m₂ = −{0}).": "For the perpendicular: pick a point and a line on the plot. For the bisector: pick two points. Includes solution steps and the relationship between the slopes (m₁·m₂ = −{0}).",
"Für diese Funktion konnte keine elementare Stammfunktion gefunden werden.": "No elementary antiderivative could be found for this function.",
"Für n gerade: achsensymmetrisch, Definitionsbereich ℝ. Für n ungerade: punktsymmetrisch, Definitionsbereich ℝ. Für n {0} {1}: Pol bei x = {2}, hyperbelartig.": "For even n: symmetric about the y-axis, domain ℝ. For odd n: symmetric about the origin, domain ℝ. For n {0} {1}: pole at x = {2}, hyperbola-like.",
"Für x → {0}: Zähler bleibt konstant ({1}), Nenner wächst über alle Grenzen (Wurzelterm dominiert)": "As x → {0}: the numerator stays constant ({1}), the denominator grows without bound (the root term dominates)",
"Für x → {0}: Zähler und Nenner wachsen beide linear in x — das Verhältnis der Leitkoeffizienten ergibt den Grenzwert:": "As x → {0}: numerator and denominator both grow linearly in x — the ratio of the leading coefficients gives the limit:",
"Für x → ±∞: {0}/({1}) → {2}": "As x → ±∞: {0}/({1}) → {2}",
"Für {0} strebt der Summand {1} gegen {2} (Exponentialfunktion mit abnehmendem Exponenten). Es bleibt der Rest:": "For {0}, the summand {1} tends to {2} (exponential function with decreasing exponent). What remains is the remainder:",
"Gebrochen-rationale Funktion": "Rational function",
"Gekürzt (für x ≠ {0}): {1} = [{2}] / [{3}]": "Simplified (for x ≠ {0}): {1} = [{2}] / [{3}]",
"Gekürzte Funktion": "Reduced function",
"Gemeinsamer Punkt zweier Graphen. Berechnung durch Gleichsetzen: {0} = {1} nach x auflösen, dann y = {2} berechnen.": "Common point of two graphs. Calculated by setting equal: solve {0} = {1} for x, then compute y = {2}.",
"Geometrische Darstellung der Steigung am Graphen: Man wählt zwei Punkte, zieht eine waagrechte Strecke (Δx) und eine senkrechte Strecke (Δy). Die Steigung ist m = Δy/Δx.": "Geometric representation of the slope on the graph: choose two points, draw a horizontal segment (Δx) and a vertical segment (Δy). The slope is m = Δy/Δx.",
"Gerade aufschalten, dann m und q oben mit den Schiebereglern verändern.": "Add the line, then adjust m and q with the sliders above.",
"Gerade, die den Graphen im Punkt (x₀ | {0}) berührt. Die Steigung der Tangente ist gleich {1}. Die Tangente ist die beste lineare Näherung des Graphen an dieser Stelle.": "A line that touches the graph at the point (x₀ | {0}). The slope of the tangent equals {1}. The tangent is the best linear approximation of the graph at that point.",
"Gerade, die den Graphen in zwei Punkten schneidet. Die Steigung der Sekante entspricht dem Differenzenquotienten — der durchschnittlichen Änderungsrate.": "A line that intersects the graph at two points. The slope of the secant equals the difference quotient — the average rate of change.",
"Geradengleichung": "Line equation",
"Geradengleichung:": "Line equation:",
