"Umkehrfunktion von f{0}: Spiegelbild an y = x einblenden": "Inverse function of f{0}: show reflection in y = x",
"Umkehrfunktion von f{0}: Spiegelbild an y = x ausblenden": "Inverse function of f{0}: hide reflection in y = x",
"f{0} Umkehrfunktion": "f{0} inverse function",
"Der Graph der Umkehrfunktion entsteht durch Spiegeln von f{0} an der Winkelhalbierenden y = x (gestrichelt).": "The graph of the inverse function is obtained by reflecting f{0} in the line y = x (dashed).",
"Diese Funktion ist auf ihrem jetzigen Definitionsbereich <0>nicht umkehrbar</0>: Zu manchen y-Werten gibt es mehrere x-Werte, das Spiegelbild ist keine Funktion.": "On its current domain this function is <0>not invertible</0>: some y-values belong to several x-values, so the reflection is not a function.",
"Einschränken des Definitionsbereichs auf:": "Restrict the domain to:",
"Als neue Funktion einfügen": "Insert as new function",
"Für diese Funktion lässt sich kein einfacher Term der Umkehrfunktion bilden. Das Spiegelbild wird trotzdem gezeigt.": "No simple expression for the inverse function can be found for this function. The reflection is still shown.",
"Eine konstante Funktion ist nicht umkehrbar (jeder y-Wert gehört zu allen x).": "A constant function is not invertible (every y-value belongs to all x).",
