"Die Gleichung ist immer wahr: jede Zahl ist eine Lösung.": "The equation is always true: every number is a solution.",
"Die Gleichung ist nie wahr: es gibt keine Lösung.": "The equation is never true: there is no solution.",
"Nach x² auflösen": "Solve for x²",
"Wurzel ziehen": "Take the root",
