"Potenzen, Wurzeln": "Powers, roots",
"Potenzen und Wurzeln": "Powers and roots",
"Eigene Aufgabe eingeben": "Enter your own problem",
"leicht": "easy",
"mittel": "medium",
"schwer": "hard",
"Potenzen mit ^ schreiben, z. B. (a^{0}·b)^{1} / (a·b^{2}), {3}^{4}·{5}^{6} oder x^-{7}. Auch Wurzeln und gebrochene Hochzahlen: sqrt({8}), root({9}, x), {10}^({11}/{12}), x^({13}/{14}).": "Write powers with ^, e.g. (a^{0}·b)^{1} / (a·b^{2}), {3}^{4}·{5}^{6} or x^-{7}. Roots and fractional exponents work too: sqrt({8}), root({9}, x), {10}^({11}/{12}), x^({13}/{14}).",
"Jede Hochzahl ist eine Reihe von Bausteinen: Multiplizieren legt Reihen aneinander, Dividieren kürzt Bausteine weg. Eine Hochzahl m/n besteht aus m Bruchbausteinen der Breite {0}/n.": "Every exponent is a row of building blocks: multiplying puts rows side by side, dividing cancels blocks. An exponent m/n consists of m fractional blocks of width {0}/n.",
"Der Logarithmus fragt nach der Hochzahl: «{0} hoch wie viel ergibt {1}?» Er ist die Umkehrung des Potenzierens. Unten steht der Rechenweg Schritt für Schritt.": "The logarithm asks for the exponent: “{0} to the power of what gives {1}?” It is the inverse of exponentiation. The working is shown step by step below.",
"<0>Zwischen zwei ganzen Zahlen</0>{1}": "<0>Between two whole numbers</0>{1}",
"Zwischen zwei ganzen Zahlen": "Between two whole numbers",
"«{0} hoch wie viel ergibt {1}?» Es ist {2}³ = {3}, also ist log₂ {4} = {5}.": "“{0} to the power of what gives {1}?” It is {2}³ = {3}, so log₂ {4} = {5}.",
"Zerlege in einzelne Logarithmen:": "Split into separate logarithms:",
"Fasse zu einem Logarithmus zusammen:": "Combine into one logarithm:",
"Gleiche Faktoren in Zähler und Nenner kürzt man. Die Definitionsmenge sagt, wo der Nenner null würde. Unten steht der Rechenweg Schritt für Schritt.": "Equal factors in numerator and denominator are cancelled. The domain tells you where the denominator would be zero. The working is shown step by step below.",
"{0} = {1}·{2}·{3} und {4} = {5}·{6}·{7}: Die gemeinsamen Faktoren {8} und {9} werden gekürzt, es bleibt {10}/{11}.": "{0} = {1}·{2}·{3} and {4} = {5}·{6}·{7}: the common factors {8} and {9} are cancelled, leaving {10}/{11}.",
"Im Graphen schneidet die Kurve y = {0}ˣ die Gerade y = {1} bei x ≈ {2}. Rechnerisch ist das x = log₂ {3}.": "In the graph the curve y = {0}ˣ meets the line y = {1} at x ≈ {2}. By calculation this is x = log₂ {3}.",
"<0>Wurzel und rationale Hochzahl</0>{1}": "<0>Root and rational exponent</0>{1}",
"<0>Gleichung und Äquivalenzumformung</0>{1}": "<0>Equation and equivalence transformation</0>{1}",
