"Nächster Klick: Bringtag festlegen": "Next click: set the day of deposit",
"Nächster Klick: Holtag festlegen": "Next click: set the day of withdrawal",
"Der Bringtag zählt nicht, der Holtag zählt. Klicke im Kalender zuerst den Bringtag, dann den Holtag an.": "The day of deposit is not counted, the day of withdrawal is. In the calendar, click the day of deposit first, then the day of withdrawal.",
"Tage": "days",
"Endwert": "final value",
"zum Vergleich:": "for comparison:",
"Urnenmodelle (Ziehen von Kugeln)": "Urn models (drawing balls)",
"Aus einer Urne mit n nummerierten Kugeln werden k Kugeln gezogen. Zwei Fragen legen das Modell fest: Wird zurückgelegt? Zählt die Reihenfolge?": "From an urn with n numbered balls, k balls are drawn. Two questions determine the model: Is the ball put back? Does the order matter?",
"Beobachte: Die vier Kombinationen ergeben vier Zählformeln. Mit «Neue Ziehung» siehst du ein Beispiel; die Rechnung zeigt die Anzahl der Möglichkeiten und die Wahrscheinlichkeit.": "Observe: the four combinations give four counting formulas. With “New draw” you see an example; the calculation shows the number of possibilities and the probability.",
"Eine Variante erklären": "Explain one variant",
"Alle vier vergleichen": "Compare all four",
"Kugeln in der Urne n": "Balls in the urn n",
"Gezogene Kugeln k": "Balls drawn k",
"{0} <1>Mit Zurücklegen</1>": "{0} <1>With replacement</1>",
"{0} <1>Mit Reihenfolge</1>": "{0} <1>Order matters</1>",
"Neue Ziehung": "New draw",
"Gezogene Kugeln bleiben draussen. Beim ersten Zug hat man n Möglichkeiten, beim zweiten n − {0}, … beim k-ten n − k + {1}. Die Reihenfolge zählt. Multiplikationsprinzip: n · (n − {2}) · … · (n − k + {3}) = n!/(n − k)!.": "Drawn balls stay out. At the first draw there are n possibilities, at the second n − {0}, … at the k-th n − k + {1}. The order matters. Multiplication principle: n · (n − {2}) · … · (n − k + {3}) = n!/(n − k)!.",
"Alle {0} Möglichkeiten sind gleich wahrscheinlich.": "All {0} possibilities are equally likely.",
"Urne mit {0} Kugeln, {1} werden gezogen": "Urn with {0} balls, {1} are drawn",
"Urne mit {0} Kugeln, eine wird gezogen": "Urn with {0} balls, one is drawn",
"zurücklegen": "put back",
"Folge der gezogenen Kugeln (Reihenfolge zählt)": "Sequence of drawn balls (order matters)",
"Menge der gezogenen Kugeln (Reihenfolge egal)": "Set of drawn balls (order does not matter)",
"Variation ohne Wiederholung": "Variation without repetition",
"Variation mit Wiederholung": "Variation with repetition",
"Kombination ohne Wiederholung": "Combination without repetition",
"Kombination mit Wiederholung": "Combination with repetition",
"ohne Zurücklegen, mit Reihenfolge": "without replacement, order matters",
"mit Zurücklegen, mit Reihenfolge": "with replacement, order matters",
"ohne Zurücklegen, ohne Reihenfolge": "without replacement, order does not matter",
"mit Zurücklegen, ohne Reihenfolge": "with replacement, order does not matter",
"Anzahl Möglichkeiten:": "Number of possibilities:",
"Wahrscheinlichkeit für das gezogene Ergebnis:": "Probability of the drawn result:",
"Jede gezogene Kugel wird zurückgelegt, darum hat man bei jedem der k Züge wieder n Möglichkeiten. Die Reihenfolge zählt: ({0}, {1}) und ({2}, {3}) sind verschieden. Multiplikationsprinzip: n · n · … · n mit k Faktoren.": "Every drawn ball is put back, so each of the k draws again has n possibilities. The order matters: ({0}, {1}) and ({2}, {3}) are different. Multiplication principle: n · n · … · n with k factors.",
"Es zählt nur, welche Kugeln gezogen wurden (wie bei einem Griff in die Urne). Jede Auswahl von k Kugeln lässt sich auf k! Arten anordnen. Darum teilt man die Zahl der Variationen n!/(n − k)! durch k!. Das ist der Binomialkoeffizient «n über k».": "Only which balls were drawn matters (like grabbing a handful from the urn). Every selection of k balls can be arranged in k! ways. So the number of variations n!/(n − k)! is divided by k!. This is the binomial coefficient “n choose k”.",
"Die Kugeln werden zurückgelegt, aber nur die gezogene Menge zählt: Kugeln dürfen mehrfach vorkommen, die Reihenfolge nicht. Zählen mit Sternen und Strichen: k Kugeln («Sterne») und n − {0} Trennstriche zwischen den n Nummern ergeben n + k − {1} Plätze, auf denen man k für die Sterne wählt.": "The balls are put back, but only the drawn collection counts: balls may appear several times, the order does not matter. Counting with stars and bars: k balls (“stars”) and n − {0} dividers between the n numbers make n + k − {1} places, from which one chooses k for the stars.",
"Die Möglichkeiten sind nicht gleich wahrscheinlich: Mengen mit verschiedenen Kugeln kommen häufiger vor.": "The possibilities are not equally likely: sets with different balls occur more often.",
"k = n: Alle Kugeln werden gezogen (Permutation).": "k = n: all balls are drawn (permutation).",
"Ohne Zurücklegen: Jede Auswahl lässt sich auf k! Arten anordnen. Variationen = k! · Kombinationen:": "Without replacement: every selection can be arranged in k! ways. Variations = k! · combinations:",
"Mit Zurücklegen gibt es meistens mehr Möglichkeiten als ohne.": "With replacement there are usually more possibilities than without.",
"Die vier Urnenmodelle im Vergleich: {0} Kugeln, {1} werden gezogen": "The four urn models compared: {0} balls, {1} are drawn",
"mit Reihenfolge": "order matters",
"ohne Reihenfolge": "order does not matter",
"ohne Zurücklegen": "without replacement",
"mit Zurücklegen": "with replacement",
"Beispiel:": "Example:",
"Ohne Zurücklegen kann man nicht mehr Kugeln ziehen, als in der Urne liegen (k ≤ n).": "Without replacement you cannot draw more balls than are in the urn (k ≤ n).",
"nicht möglich (k {0} n)": "not possible (k {0} n)",
