"Partielle Integration oder Substitution": "Integration by parts or substitution",
"Die Fläche zwischen f und der x-Achse (oder zwischen f und g) wird an den Schnittstellen in Stücke geteilt. Stücke über der Achse (bzw. über g) sind grün, darunter orange.": "The area between f and the x-axis (or between f and g) is split into pieces at the intersections. Pieces above the axis (or above g) are green, below it orange.",
"Flächen zählen immer positiv: Beim Integral heben sich grüne und orange Stücke teilweise auf, bei der Fläche nicht.": "Areas always count as positive: in the integral, green and orange pieces partly cancel; in the area they do not.",
