"Eine lineare Funktion {0} = m·x + q hat als Graph eine Gerade. Die Steigung m sagt, um wie viel y pro Schritt {1} nach rechts wächst (Steigungsdreieck), q ist der y-Achsenabschnitt.": "A linear function {0} = m·x + q has a straight line as its graph. The slope m tells by how much y increases per step of {1} to the right (slope triangle); q is the y-intercept.",
"Ziehe den violetten Punkt S, um q zu ändern, oder verändere m mit dem Regler. Die Wertetabelle zeigt, dass y bei jedem Schritt um m wächst.": "Drag the violet point S to change q, or change m with the slider. The table of values shows that y increases by m with every step.",
