"Gerade und Parabel: Gleichsetzen gibt eine quadratische Gleichung, deren Diskriminante die Anzahl der Schnittpunkte bestimmt (Sekante, Tangente, Passante). Umgekehrt legen drei Punkte, oder Scheitel und Punkt, oder zwei Nullstellen und ein Punkt eine Parabel fest.": "Line and parabola: setting equal gives a quadratic equation whose discriminant determines the number of intersection points (secant, tangent, passing line). Conversely, three points, or vertex and point, or two roots and a point determine a parabola.",
