"<0>Umkehrung:</0> Die Wurzelfunktion macht das Potenzieren rückgängig. Aus {1} wird nach {2} aufgelöst (nur für {3}, damit die Zuordnung eindeutig ist), dann werden {4} und {5} vertauscht.": "<0>Inversion:</0> The root function undoes raising to a power. From {1}, solve for {2} (only for {3}, so that the mapping is unique), then swap {4} and {5}.",
"Der Graph der Umkehrfunktion ist das <0>Spiegelbild</0> des Graphen von {1} an der Winkelhalbierenden {2}: Jeder Punkt {3} wird zu {4}.": "The graph of the inverse function is the <0>reflection</0> of the graph of {1} in the line {2}: every point {3} becomes {4}.",
"<0>Definitions- und Wertebereich:</0> Eine gerade Wurzel aus einer negativen Zahl gibt es in {1} nicht; die Wurzel ist nie negativ.": "<0>Domain and range:</0> An even root of a negative number does not exist in {1}; the root is never negative.",
"<0>Potenzschreibweise:</0> Die Wurzel ist eine Potenz mit dem Exponenten {1}, denn {2}.": "<0>Power notation:</0> The root is a power with the exponent {1}, because {2}.",
"<0>Beispiel</0> mit {1}: erst potenzieren, dann die Wurzel ziehen.": "<0>Example</0> with {1}: first raise to the power, then take the root.",
