"Umkehrfunktion: Begriff": "Inverse function: concept",
"<0>Zuordnung rückwärts lesen:</0> {1} ordnet jedem {2} einen Wert {3} zu. Die <4>Umkehrfunktion</4> {5} macht das rückgängig: Sie ordnet jedem Wert {6} das ursprüngliche {7} zu. In der Wertetabelle werden dazu einfach die beiden Zeilen vertauscht.": "<0>Reading the assignment backwards:</0> {1} assigns to each {2} a value {3}. The <4>inverse function</4> {5} undoes this: it assigns to each value {6} the original {7}. In the table of values, the two rows are simply swapped.",
"<0>Graph:</0> Jeder Punkt {1} auf dem Graphen von {2} wird zum Punkt {3} auf dem Graphen von {4}. Koordinaten tauschen heisst <5>Spiegeln an der Winkelhalbierenden</5> {6}.": "<0>Graph:</0> Each point {1} on the graph of {2} becomes the point {3} on the graph of {4}. Swapping coordinates means <5>reflecting in the line</5> {6}.",
"<0>Bereiche tauschen:</0> Was bei {1} herauskommt (Wertebereich), darf bei {2} hinein (Definitionsbereich), und umgekehrt.": "<0>Swapping the sets:</0> What comes out of {1} (range) may go into {2} (domain), and vice versa.",
"Schreibweise: {0} ist <1>nicht</1> {2}; die {3} bedeutet Umkehrung, nicht Kehrwert.": "Notation: {0} is <1>not</1> {2}; the {3} means inverse, not reciprocal.",
"{0} ordnet jedem Funktionswert sein {1} zu; der Graph ist das Spiegelbild von {2} an {3}": "{0} assigns to each function value its {1}; the graph is the mirror image of {2} in {3}",
"{0} Ziehe den Punkt P auf f: Sein Spiegelpunkt liegt auf der Umkehrfunktion. Oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Drag the point P on f: its mirror point lies on the inverse function. Choose the view at the top left; the working is on the right.",
"Erkannt: lineare Funktion – auf D umkehrbar.": "Recognised: linear function – invertible on D.",
"Erkannt: Potenz-/Wurzelfunktion – nur eingeschränkt umkehrbar (x ≥ {0}, rechter Ast).": "Recognised: power/root function – invertible only with restriction (x ≥ {0}, right-hand branch).",
"{0} ist nur auf dem eingeschränkten Bereich {1} umkehrbar (sonst gehören zu einem {2} zwei {3}); der andere Ast ist grau gezeichnet.": "{0} is invertible only on the restricted set {1} (otherwise two {3} belong to one {2}); the other branch is drawn in grey.",
"Erkannt: Exponentialfunktion – auf D umkehrbar.": "Recognised: exponential function – invertible on D.",
"Erkannt: Logarithmusfunktion – auf D umkehrbar.": "Recognised: logarithmic function – invertible on D.",
"Erlaubt sind lineare Funktionen, a·(x−v)^n + h, Wurzeln, a/(x−v)^n + h, a·b^x + d und a·log_b(x−v) + d (ln, lg).": "Permitted are linear functions, a·(x−v)^n + h, roots, a/(x−v)^n + h, a·b^x + d and a·log_b(x−v) + d (ln, lg).",
"Umkehrbar ist eine Funktion nur, wenn jeder Wert höchstens einmal vorkommt: Jede waagrechte Gerade darf den Graphen höchstens einmal schneiden. Streng monotone Funktionen erfüllen das. Sonst hilft eine Einschränkung des Definitionsbereichs.": "A function is invertible only if every value occurs at most once: every horizontal line may meet the graph at most once. Strictly monotonic functions satisfy this. Otherwise a restriction of the domain helps.",
"Ziehe die orange Gerade y = k auf und ab und zähle die Schnittpunkte. Bei x² und Co. kannst du die rote Grenze r der Einschränkung verschieben.": "Drag the orange line y = k up and down and count the intersection points. For x² and the like you can move the red boundary r of the restriction.",
