"Die Umkehrfunktion berechnet man in drei Schritten: y = {0} nach x auflösen (Rechenschritte rückgängig machen), dann x und y vertauschen, dann Definitions- und Wertebereich tauschen.": "The inverse function is computed in three steps: solve y = {0} for x (undo the operations), then swap x and y, then swap domain and range.",
