"Rechenweg: Balken und Graph": "Working: bars and graph",
"<0>Stellen im Abstand</0> {1}: Über jeder Stelle {2} steht ein Balken von der {3}-Achse bis zur Höhe {4}. Ein negativer Wert gibt einen Balken nach unten.": "<0>Inputs at spacing</0> {1}: Above each input {2} stands a bar from the {3}-axis up to the height {4}. A negative value gives a bar pointing downwards.",
"<0>Je kleiner der Abstand,</0> desto mehr Balken: Bei {1} sind es im Bild {2}. Lässt man {3} gegen {4} gehen, verschmelzen die Balkenenden zur Kurve.": "<0>The smaller the spacing,</0> the more bars: at {1} there are {2} in the picture. If {3} is allowed to tend to {4}, the bar ends merge into the curve.",
"Der Graph ist die Linie durch alle Balkenenden {0} – für jede Stelle {1} genau ein Punkt": "The graph is the line through all the bar ends {0} – exactly one point for each input {1}",
"<0>Abstand {1}:</0> Es gibt unendlich viele Stellen; die Balken rücken so dicht zusammen, dass nur noch ihre oberen Enden sichtbar sind – das ist der <2>Graph</2> der Funktion, eine durchgehende Kurve.": "<0>Spacing {1}:</0> There are infinitely many inputs; the bars move so close together that only their upper ends remain visible – that is the <2>graph</2> of the function, a continuous curve.",
"Der Graph ist die Menge aller Punkte {0}": "The graph is the set of all points {0}",
"Abstand {0}: die ganze Kurve": "Spacing {0}: the whole curve",
"Begriffe am Graphen: Definitionsbereich (welche x darf man einsetzen), Wertebereich (welche Werte kommen heraus), Nullstellen, y-Achsenabschnitt, steigend und fallend, Hoch- und Tiefpunkte. Jede senkrechte Gerade trifft den Graphen höchstens einmal.": "Terms on the graph: domain (which x may be substituted), range (which values come out), zeros, y-intercept, increasing and decreasing, maximum and minimum points. Every vertical line meets the graph at most once.",
"Ziehe die violette Gerade x = t über das Bild. Blende den Kreis ein: Er wird zweimal getroffen und ist darum kein Funktionsgraph.": "Drag the purple line x = t across the picture. Show the circle: it is met twice and is therefore not the graph of a function.",
