"Funktionen beschreiben Zusammenhänge zwischen Grössen: Weg und Zeit, Kosten und Minuten, Temperatur und Uhrzeit. Die Achsen tragen dann Grössen mit Einheiten, und jeder Funktionswert hat eine Bedeutung.": "Functions describe relationships between quantities: distance and time, cost and minutes, temperature and time of day. The axes then carry quantities with units, and every function value has a meaning.",
