// Easter-Eggs (24_eggs.js)
"Parallele Geraden schneiden sich nie – oder, wie man in der projektiven Geometrie sagt: im Unendlichen. So weit kann man leider nicht zoomen.": "Parallel lines never meet – or, as projective geometry puts it: at infinity. Unfortunately you can't zoom out that far.",
"Punktlandung: D = {0}. Die Parabel berührt die x-Achse in genau einem Punkt – eine doppelte Nullstelle.": "Bull's-eye: D = {0}. The parabola touches the x-axis at exactly one point – a double zero.",
"Wachstum mit Basis {0}? {1} · {2} · {3} · … bleibt {4}. Kein Wachstum, kein Zerfall – nur eine waagrechte Gerade.": "Growth with base {0}? {1} · {2} · {3} · … stays {4}. No growth, no decay – just a horizontal line.",
"f = f⁻¹: Diese Funktion ist ihr eigenes Spiegelbild an y = x. Zweimal anwenden ergibt wieder x.": "f = f⁻¹: This function is its own mirror image in y = x. Applying it twice gives x again.",
"f′ = f: Diese Funktion ist ihre eigene Ableitung. Das schaffen nur die Funktionen c · eˣ.": "f′ = f: This function is its own derivative. Only the functions c · eˣ can do that.",
"Der kleine Gauss": "Little Gauss",
"Der Legende nach stellte der Lehrer Büttner um {0} seiner Klasse die Aufgabe, alle Zahlen von {1} bis {2} zu addieren – er wollte eine Weile Ruhe. Der neunjährige Carl Friedrich Gauss war nach wenigen Augenblicken fertig:": "Legend has it that around {0} the teacher Büttner set his class the task of adding all numbers from {1} to {2} – he wanted some peace and quiet. Nine-year-old Carl Friedrich Gauss was done within moments:",
"Die Reihe rückwärts darunter schreiben: Jede Spalte ergibt {0}, und es sind {1} Spalten. Das ist die Summe zweimal, also s = {2} · {3} / {4}. Dieselbe Idee steckt in der Formel sₙ = n · (a₁ + aₙ) / {5}.": "Write the series backwards underneath: each column gives {0}, and there are {1} columns. That is the sum twice, so s = {2} · {3} / {4}. The same idea is behind the formula sₙ = n · (a₁ + aₙ) / {5}.",
"Unentschieden! Die Niveaulinie liegt parallel zu einer Kante des Planungspolygons: Alle Punkte dieser Kante sind optimal.": "A tie! The level line is parallel to an edge of the feasible region: every point on this edge is optimal.",
"Rechter Winkel! Dann liegt die Ecke auf dem Thaleskreis über der gegenüberliegenden Seite – und umgekehrt.": "A right angle! Then the vertex lies on the Thales circle over the opposite side – and vice versa.",
"Nach {0} Spielen: Wechseln gewinnt in {1} %, Bleiben nur in {2} % der Fälle – genau wie die Theorie sagt: {3}/{4} gegen {5}/{6}.": "After {0} games: switching wins {1} % of the time, staying only {2} % – just as theory says: {3}/{4} versus {5}/{6}.",
"Aus lauter Zufall entsteht Ordnung: Nach {0} Kugeln zeigt sich die Glockenkurve der Normalverteilung.": "Order out of pure chance: after {0} balls the bell curve of the normal distribution appears.",
"Du hast die Milchstrasse verlassen. Hier draussen gibt es nur noch Pixel.": "You have left the Milky Way. Out here there are only pixels.",
"Planck-Länge erreicht – noch kleiner wird es nicht (zumindest nicht schön).": "Planck length reached – it doesn't get any smaller (at least not nicely).",
"Rosenkurve r = {0}·cos({1}φ) in Polarkoordinaten: vier Blütenblätter. Mit cos(kφ) gibt es k Blätter (k ungerade) oder {2}k (k gerade).": "Rose curve r = {0}·cos({1}φ) in polar coordinates: four petals. With cos(kφ) there are k petals (k odd) or {2}k (k even).",
"Koch-Schneeflocke: Jede Stufe macht den Rand {0}/{1}-mal so lang. Der Umfang wird unendlich, die Fläche bleibt endlich.": "Koch snowflake: each step makes the boundary {0}/{1} times as long. The perimeter becomes infinite, the area stays finite.",
"Lemniskate von Bernoulli: (x² + y²)² = {0}(x² − y²). Das Zeichen ∞ hat genau diese Form.": "Lemniscate of Bernoulli: (x² + y²)² = {0}(x² − y²). The symbol ∞ has exactly this shape.",
"sin²x + cos²x = {0} für jedes x – das ist der Satz des Pythagoras am Einheitskreis. Der Graph ist die Gerade y = {1}.": "sin²x + cos²x = {0} for every x – that is Pythagoras' theorem on the unit circle. The graph is the line y = {1}.",
"e^(iπ) + {0} = {1} – fünf wichtige Konstanten in einer Gleichung: e, i, π, {2} und {3}.": "e^(iπ) + {0} = {1} – five important constants in one equation: e, i, π, {2} and {3}.",
"{0} = {1}³ + {2}³ = {3}³ + {4}³ – die kleinste Zahl, die auf zwei Arten Summe zweier Kubikzahlen ist. Ramanujan erkannte das sofort, als Hardy die «langweilige» Taxinummer {5} erwähnte.": "{0} = {1}³ + {2}³ = {3}³ + {4}³ – the smallest number that is the sum of two cubes in two ways. Ramanujan saw this at once when Hardy mentioned the “dull” taxi number {5}.",
"{0} … Quadrate mit Fibonacci-Seiten bilden die goldene Spirale. Der Quotient zweier Nachbarn strebt gegen φ ≈ {1}.": "{0} … Squares with Fibonacci sides form the golden spiral. The ratio of two neighbours tends to φ ≈ {1}.",
"Ja, wirklich: {0}… (unendlich viele Neunen) ist genau {1}. Drei Begründungen:": "Yes, really: {0}… (infinitely many nines) is exactly {1}. Three reasons:",
"Zwischen zwei verschiedenen Zahlen liegt immer eine dritte. Zwischen {0}… und {1} passt aber keine Zahl – also sind sie gleich.": "Between two different numbers there is always a third. But no number fits between {0}… and {1} – so they are equal.",
"Eine Zahl kann mehrere Dezimaldarstellungen haben: {0} = {1}… = {2}…": "A number can have several decimal representations: {0} = {1}… = {2}…",
"Fast! Das Quadrat mit der Seite a + b besteht aus vier Teilen: a², b² und zweimal dem Rechteck a·b. Darum gilt (a + b)² = a² + {0}ab + b².": "Almost! The square with side a + b consists of four parts: a², b² and twice the rectangle a·b. That is why (a + b)² = a² + {0}ab + b².",
"Die orangen Rechtecke sind die «fehlenden» {0}ab.": "The orange rectangles are the “missing” {0}ab.",
"Fast! Beim Quadrieren einer Differenz fehlt das gemischte Glied: (a − b)² = a² − {0}ab + b². Das Bild zeigt es für eine Summe; bei der Differenz werden die beiden Rechtecke abgezogen.": "Almost! When squaring a difference, the mixed term is missing: (a − b)² = a² − {0}ab + b². The picture shows it for a sum; for the difference the two rectangles are subtracted.",
"Collatz-Vermutung": "Collatz conjecture",
"Regel: Ist die Zahl gerade, halbiere sie. Ist sie ungerade, rechne {0}n + {1}. Jede je getestete Startzahl landet irgendwann im Kreis {2} → {3} → {4}. Ob das für alle Zahlen gilt, weiss bis heute niemand.": "Rule: if the number is even, halve it. If it is odd, compute {0}n + {1}. Every starting number ever tested eventually ends in the loop {2} → {3} → {4}. Whether this holds for all numbers, nobody knows to this day.",
